    22  static int
    23  avail_comp (void const *a, void const *b)
    24  {
    25    avail_elem const *ava = a;
    26    avail_elem const *avb = b;
    27    if (ava->av_size < avb->av_size)
    28      return -1;
    29    else if (ava->av_size > avb->av_size)
    30      return 1;
    31    return 0;
    32  }
