    77  int
    78  gdbm_avail_block_validate (GDBM_FILE dbf, avail_block *avblk, size_t size)
    79  {
    80    if (!(size > sizeof (avail_block)
    81          && (avblk->size > 1 && avblk->count >= 0 && avblk->count <= avblk->size)
    82          && ((size - sizeof (avail_block)) / sizeof (avail_elem) + 1) >= avblk->count
    83          && gdbm_avail_table_valid_p (dbf, avblk->av_table, avblk->count)))
    84      {
    85        GDBM_SET_ERRNO (dbf, GDBM_BAD_AVAIL, TRUE);
    86        return -1;
    87      }
    88    return 0;
    89  }
