   120  static int
   121  off_map_expand (struct off_map *map)
   122  {
   123    size_t n = map->map_max;
   124    void *p;
   125
   126    if (!map->map_base)
   127      {
   128        if (!n)
   129          n = 64;
   130      }
   131    else
   132      {
   133        if (SIZE_T_MAX / 3 * 2 / sizeof (map->map_base[0]) <= n)
   134          {
   135            errno = ENOMEM;
   136            return -1;
   137          }
   138        n += (n + 1) / 2;
   139      }
   140
   141    p = realloc (map->map_base, n * sizeof (map->map_base[0]));
   142    if (!p)
   143      return -1;
   144    map->map_base = p;
   145    map->map_max = n;
   146    return 0;
   147  }
